/// The set of categories a name refers to, if any.
#[must_use]
pub fn category_set(name: &str) -> Option<&'static CategorySet> {
    CATEGORY_SETS
        .iter()
        .find(|candidate| candidate.name == name)
}

/// The category a name refers to, if any.
#[must_use]
pub fn category(name: &str) -> Option<&'static Category> {
    CATEGORIES.iter().find(|candidate| candidate.name == name)
}
